head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldbnf90001";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf90001.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_44", fn: function(){ return (String((dma_result.get("isurCd") ?? (() => { throw new Error("unresolved:" + "result.isurCd"); })())).substring(0, 2) === 'MB'); } }, { id: "tr_45", fn: function(){ return (String((dma_result.get("isurCd") ?? (() => { throw new Error("unresolved:" + "result.isurCd"); })())).substring(0, 2) === 'MB'); } }, { id: "if_coupnRtFinalYn_txt", fn: function(){ return ((dma_result.get("coupnRtFinalYn") ?? (() => { throw new Error("unresolved:" + "result.coupnRtFinalYn"); })()) === 'Y'); } }, { id: "c_when_124", fn: function(){ return ((dma_result.get("isurCd") ?? (() => { throw new Error("unresolved:" + "result.isurCd"); })()) === 'GB035'); } }, { id: "tr_125", fn: function(){ return ((dma_result.get("isurCd") ?? (() => { throw new Error("unresolved:" + "result.isurCd"); })()) === 'GB035'); } }, { id: "c_otherwise_130", fn: function(){ return (!(((dma_result.get("isurCd") ?? (() => { throw new Error("unresolved:" + "result.isurCd"); })()) === 'GB035'))); } }, { id: "c_when_176", fn: function(){ return ((dma_result.get("isurCd") ?? (() => { throw new Error("unresolved:" + "result.isurCd"); })()) === 'GB035'); } }, { id: "tr_177", fn: function(){ return ((dma_result.get("isurCd") ?? (() => { throw new Error("unresolved:" + "result.isurCd"); })()) === 'GB035'); } }, { id: "if_sfValuYn_txt", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "list.sfValuYn"); })() === 'Y'); } }, { id: "c_when_249", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "list.bndUdwrtInstOrd"); })() < 5); } }, { id: "c_when_251", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "list.bndUdwrtInstOrd"); })() === '5'); } }, { id: "tr_252", fn: function(){ return ((() => { throw new Error("unresolved:data:" + "list.bndUdwrtInstOrd"); })() === '5'); } }, { id: "c_otherwise_254", fn: function(){ return (!(((() => { throw new Error("unresolved:data:" + "list.bndUdwrtInstOrd"); })() < 5) || ((() => { throw new Error("unresolved:data:" + "list.bndUdwrtInstOrd"); })() === '5'))); } }, { id: "c_when_244", fn: function(){ return (!(String(((dma_ht.get("udwrtInstList") ?? (() => { throw new Error("unresolved:" + "ht.udwrtInstList"); })())) == null ? '' : ((dma_ht.get("udwrtInstList") ?? (() => { throw new Error("unresolved:" + "ht.udwrtInstList"); })()))).length === 0)); } }, { id: "tr_245", fn: function(){ return (!(String(((dma_ht.get("udwrtInstList") ?? (() => { throw new Error("unresolved:" + "ht.udwrtInstList"); })())) == null ? '' : ((dma_ht.get("udwrtInstList") ?? (() => { throw new Error("unresolved:" + "ht.udwrtInstList"); })()))).length === 0)); } }, { id: "tr_252", fn: function(){ return (!(String(((dma_ht.get("udwrtInstList") ?? (() => { throw new Error("unresolved:" + "ht.udwrtInstList"); })())) == null ? '' : ((dma_ht.get("udwrtInstList") ?? (() => { throw new Error("unresolved:" + "ht.udwrtInstList"); })()))).length === 0)); } }, { id: "tr_255", fn: function(){ return (!(String(((dma_ht.get("udwrtInstList") ?? (() => { throw new Error("unresolved:" + "ht.udwrtInstList"); })())) == null ? '' : ((dma_ht.get("udwrtInstList") ?? (() => { throw new Error("unresolved:" + "ht.udwrtInstList"); })()))).length === 0)); } }, { id: "if_nusualBndTpCd", fn: function(){ return ((dma_result.get("nusualBndTpCd") ?? (() => { throw new Error("unresolved:" + "result.nusualBndTpCd"); })()) === '2'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_fillGen
 * @description 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
 * @param {String} boxId boxId
 * @returns {void}
 * @hidden N
 */
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_235", entity: "dlt_htCreditList", countIds: [], cells: [{ childId: "__rc68", fn: function (v, i) { return String(v("creditValuInstNm")); } }, { childId: "__rc69", fn: function (v, i) { return String(v("byinstCreditValuGrd")); } }] },
        { genId: "c_foreach_247", entity: "dlt_htUdwrtInstList", countIds: [], cells: [{ childId: "__rc70", fn: function (v, i) { return String(v("udwrtInstNm")) + " / " + String(v("udwrtAmt")); } }, { childId: "__rc71", fn: function (v, i) { return "기타금액 / " + String(v("udwrtAmt")); } }, { childId: "__rc72", fn: function (v, i) { return String(v("udwrtInstNm")) + " / " + String(v("udwrtAmt")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return "(" + String(dma_result.get("isurCd")) + ") " + String(String((dma_pageContext.get("isurNm") ?? ""))); } },
        { childId: "__rb59", fn: function () { return "시설자금: " + String(dma_result.get("eqmtFnd")); } },
        { childId: "__rb60", fn: function () { return "운영자금: " + String(dma_result.get("operFnd")); } },
        { childId: "__rb61", fn: function () { return "차환자금: " + String(dma_result.get("refundFnd")); } },
        { childId: "__rb62", fn: function () { return "기타자금: " + String(dma_result.get("miscFnd")); } },
        { childId: "__rb80", fn: function () { return String(dma_result.get("cashPayYnNm")) + " " + String(dma_result.get("sbPayYnNm")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

// [A] 초기 목록 미해결 — jldbnf90001: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_self_onclick
 * @description btn_self 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_self_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf90001.btn_self_onclick' }); }
};
